fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let target_width = width as usize;

    if orig_len >= target_width {
        // Original sequence is already at least as long as target width,
        // so return it unchanged.
        orig
    } else {
        // Need to pad the sequence on the left with fillchar,
        // so that the total length is target_width and orig
        // appears as a suffix.
        let mut result = Vec::with_capacity(target_width);
        // Number of fill characters to prepend
        let pad_len = target_width - orig_len;

        // Push the fillchar pad_len times
        for _ in 0..pad_len {
            result.push(fillchar);
        }

        // Push all original chars
        result.extend(orig);

        result
    }
}